1	import java.util.List;
2	import java.util.Random;
3	import java.util.Set;
4	import java.util.HashSet;
5	
6	/**
7	 * A class representing shared characteristics of actors.
8	 *
9	 * @version 27.02.22
10	 */
11	public abstract class Actor
12	{
13	    // Whether the actor is alive or not.
14	    private boolean alive;
15	    // The actor's field.
16	    private Field field;
17	    // The actor's position in the field.
18	    private Location location;
19	    //The actor's age
20	    protected int age;
21	    //A reference to the time object of the simulation
22	    private Time time; 
23	    //The diseases that the actor has
24	    protected Set<Disease> setDiseases;
25	    //If the animal can go on water
26	    protected boolean canGoWater;
27	    //If the animal can go on land
28	    protected boolean canGoLand;
29	
30	    /**
31	     * Create a new actor at location in field with time as well.
32	     * With a set that will add any disease that it catches
33	     * 
34	     * @param field The field currently occupied.
35	     * @param location The location within the field.
36	     * @param time The time in the simulation
37	     */
38	    public Actor(Time time, Field field, Location location)
39	    {
40	        alive = true;
41	        this.field = field;
42	        setLocation(location);
43	        this.time = time;
44	        setDiseases = new HashSet<>();
45	    }
46	
47	    /**
48	     * Make this actor act - that is: make it do
49	     * whatever it wants/needs to do.
50	     * Checks if the location it is in is land or water, if it is in a location where
51	     * it can not be in, it will die by either being on water when it can only be on land vice versa
52	     * @param newActors A list to receive newly born actors.
53	     * @param weather The weather condition of the simulation.
54	     */
55	    public void act(List<Actor> newActors, WeatherCond weather)
56	    {
57	        incrementAge();
58	        if(isAlive() && ((!field.isUnderWater(location.getRow(), location.getCol()) && !canMoveOnLand()) || (field.isUnderWater(location.getRow(), location.getCol()) && !canMoveOnWater()))) {
59	            setDead();
60	        }
61	    }
62	
63	    /**
64	     * Check whether the actor is alive or not.
65	     * @return true if the actor is still alive.
66	     */
67	    protected boolean isAlive()
68	    {
69	        return alive;
70	    }
71	
72	    /**
73	     * Indicate that the actor is no longer alive.
74	     * It is removed from the field.
75	     */
76	    protected void setDead()
77	    {
78	        alive = false;
79	        if(location != null) {
80	            field.clear(this, location);
81	            location = null;
82	            field = null;
83	        }
84	    }
85	
86	    /**
87	     * Return the actor's location.
88	     * @return The actor's location.
89	     */
90	    protected Location getLocation()
91	    {
92	        return location;
93	    }
94	
95	    /**
96	     * Place the actor at the new location in the given field.
97	     * @param newLocation The actor's new location.
98	     */
99	    protected void setLocation(Location newLocation)
100	    {
101	        if(location != null) {
102	            field.clear(this, location);
103	        }
104	        location = newLocation;
105	        field.place(this, newLocation);
106	    }
107	
108	    /**
109	     * Return the actor's field.
110	     * @return The actor's field.
111	     */
112	    protected Field getField()
113	    {
114	        return field;
115	    }
116	
117	    /**
118	     * Return the time in the field.
119	     * @return The time.
120	     */
121	    protected Time getTime()
122	    {
123	        return time;
124	    }
125	
126	    /**
127	     * Increments the actors age by 1
128	     * If the actor has a disease then the max age will decrease and if the current age
129	     * is greater than the maxAge then they will die.
130	     * Each disease reduces the maxAge by a certain amount.
131	     */
132	    private void incrementAge()
133	    {
134	        age++;
135	        int maxAge = getMaxAge();
136	        for(Disease disease : setDiseases){
137	            Double severity = disease.getActorsAffectedMap().get(getClass());
138	            if(severity != null){
139	                maxAge *= severity;
140	            }
141	        }
142	        if(age > maxAge) {
143	            setDead();
144	        }
145	    }
146	
147	    /**
148	     * Returns the actors max age
149	     * @return The max age
150	     */
151	    abstract protected int getMaxAge();
152	
153	    /**
154	     * Checks if there is free locations and places the offspring there
155	     * If the parent has diseases then those transferred by birth it will be transfered to the child
156	     * @param newActors The List of new actors that have been born to add to the simulator List of actors
157	     */
158	    protected void giveBirth(List<Actor> newActors)
159	    {
160	        Field field = getField();
161	        List<Location> free = field.getFreeAdjacentLocations(this, getLocation());
162	        int births = breed();
163	        for(int b = 0; b < births && !free.isEmpty(); b++) {
164	            Location loc = free.remove(0);
165	            newActors.add(spawnOffspring(loc, setDiseases));
166	        }
167	    }
168	
169	    /**
170	     * Returns if the actor can move on land
171	     * @return true if the actor can move on land
172	     */
173	    public boolean canMoveOnLand()
174	    {
175	        return canGoLand;
176	    }
177	
178	    /**
179	     * Returns if the actor can move on water
180	     * @return true if the actor can move on water
181	     */
182	    public boolean canMoveOnWater()
183	    {
184	        return canGoWater;
185	    }
186	    
187	    /**
188	     * Return if the actor has a disease
189	     * @return true if the actor has a disease
190	     */
191	    public boolean hasDisease(){
192	        return !setDiseases.isEmpty();
193	    }
194	    
195	    /**
196	     * Returns the set of diseases the actor has
197	     * @return The set of diseases the actor has
198	     */
199	    public Set<Disease> getActorDiseaseSet()
200	    {
201	        return setDiseases;
202	    }
203	
204	    /**
205	     * Inherit diseases from parent — called from newborn constructors.
206	     */
207	    protected void inheritDiseases(Set<Disease> parentDiseases) {
208	        for(Disease disease : parentDiseases) {
209	            if(disease.isSpreadByBirth()) {
210	                setDiseases.add(disease);
211	            }
212	        }
213	    }
214	
215	    /**
216	     * Assign starting diseases by probability — called from random-age constructors.
217	     * @param diseases The global disease list from the simulation.
218	     */
219	    protected void initStartingDiseases(List<Disease> diseases) {
220	        Random rand = Randomizer.getRandom();
221	        for(Disease disease : diseases) {
222	            Double prob = disease.getStartingActorsMap().get(getClass());
223	            if(prob != null && rand.nextDouble() <= prob) {
224	                setDiseases.add(disease);
225	            }
226	        }
227	    }
228	
229	    abstract protected int breed();
230	
231	    /** Create a newborn at loc, inheriting diseases from this actor's parent set. */
232	    abstract protected Actor spawnOffspring(Location loc, Set<Disease> parentDiseases);
233	
234	    /** Create a random-age instance at loc, used during field initialization. */
235	    abstract protected Actor spawnRandom(Location loc);
236	}
