1	import java.util.Random;
2	import java.util.Map;
3	import java.util.HashMap;
4	import java.util.Set;
5	
6	/**
7	 * A simple model of a alligator.
8	 * Alligators age, move, eat their prey, and die.
9	 *
10	 * @version 27.02.22
11	 */
12	public class Alligator extends Animal
13	{
14	    // Characteristics shared by all alligators (class variables).
15	
16	    // The age at which a alligator can start to breed.
17	    private static final int BREEDING_AGE = 15;
18	    // The age to which a alligator can live.
19	    private static final int MAX_AGE = 200;
20	    // The likelihood of a alligator breeding.
21	    private static final double BREEDING_PROBABILITY = 0.3;
22	    // The maximum number of births.
23	    private static final int MAX_LITTER_SIZE = 5;
24	    // The food value of all prey.
25	    private static final Map<Class<? extends Actor>, Integer> PREY_FOOD_VALUES = createPreyFoodValueMap();
26	    // A shared random number generator to control breeding.
27	    private static final Random rand = Randomizer.getRandom();
28	    // The max food value of the alligator. In effect, this is the
29	    // number of steps a alligator can go before it has to eat again.
30	    private static final int MAX_FOOD = 25;
31	
32	    /**
33	     * Create a alligator. The alligator is created as a new born (age zero
34	     * and not hungry).
35	     * 
36	     * @param time The time in the simulation.
37	     * @param field The field currently occupied.
38	     * @param location The location within the field.
39	     * @param parentDiseases The diseases the parent of this alligator had.
40	     */
41	    private Alligator(Time time, Field field, Location location, int age, int foodLevel)
42	    {
43	        super(time, field, location);
44	        female = rand.nextBoolean();
45	        nocturnal = false;
46	        canGoLand = true;
47	        canGoWater = true;
48	        this.age = age;
49	        this.foodLevel = foodLevel;
50	    }
51	
52	    public Alligator(Time time, Field field, Location location, Set<Disease> parentDiseases)
53	    {
54	        this(time, field, location, 0, MAX_FOOD);
55	        inheritDiseases(parentDiseases);
56	    }
57	
58	    public Alligator(Time time, Field field, Location location)
59	    {
60	        this(time, field, location, rand.nextInt(MAX_AGE), rand.nextInt(MAX_FOOD) + 1);
61	        initStartingDiseases(Simulator.diseases);
62	    }
63	
64	    /**
65	     * Create a Map with a key of the prey class
66	     * and a value of the food level is given when eaten.
67	     * @return The prey food value Map.
68	     */
69	    private static Map<Class<? extends Actor>, Integer> createPreyFoodValueMap()
70	    {
71	        Map<Class<? extends Actor>, Integer> mapTemp = new HashMap<>();
72	        mapTemp.put(Lemur.class, 8);
73	        mapTemp.put(Catfish.class, 4);
74	        return mapTemp;
75	    }
76	
77	    protected int getBreedingAge() { return BREEDING_AGE; }
78	    protected double getBreedingProbability() { return BREEDING_PROBABILITY; }
79	    protected int getMaxLitterSize() { return MAX_LITTER_SIZE; }
80	
81	    /**
82	     * Returns the max food level that the alligator can have.
83	     * @return The max food level that the alligator can have.
84	     */
85	    public int getMaxFood()
86	    {
87	        return MAX_FOOD;
88	    }
89	
90	    /**
91	     * Returns the max age that the alligator can have before dying.
92	     * @return The max age that the alligator can have before dying.
93	     */
94	    public int getMaxAge()
95	    {
96	        return MAX_AGE;
97	    }
98	
99	    /**
100	     * Returns the prey food values Map.
101	     * @return The prey food values Map.
102	     */
103	    public Map<Class<? extends Actor>, Integer> getPreyFoodValuesMap()
104	    {
105	        return PREY_FOOD_VALUES;
106	    }
107	
108	    public Animal spawnOffspring(Location loc, Set<Disease> parentDiseases)
109	    {
110	        return new Alligator(getTime(), getField(), loc, parentDiseases);
111	    }
112	
113	    public Animal spawnRandom(Location loc)
114	    {
115	        return new Alligator(getTime(), getField(), loc);
116	    }
117	}
