6	/**
7	 * A simple model of a catfish.
8	 * Catfishs age, move, eat their prey, and die.
9	 *
10	 * @version 27.02.22
11	 */
12	public class Catfish extends Animal
13	{
14	    // Characteristics shared by all catfishs (class variables).
15	
16	    // The age at which a catfish can start to breed.
17	    private static final int BREEDING_AGE = 5;
18	    // The age to which a catfish can live.
19	    private static final int MAX_AGE = 20;
20	    // The likelihood of a catfish breeding.
21	    private static final double BREEDING_PROBABILITY = 0.8;
22	    // The maximum number of births.
23	    private static final int MAX_LITTER_SIZE = 6;
24	    // The food value of all prey.
25	    private static final Map<Class<? extends Actor>, Integer> PREY_FOOD_VALUES = createPreyFoodValueMap();
26	    // A shared random number generator to control breeding.
27	    private static final Random rand = Randomizer.getRandom();
28	    // The max food value of the catfish. In effect, this is the
29	    // number of steps a catfish can go before it has to eat again.
30	    private static final int MAX_FOOD = 7;
31	    /**
32	     * Create a catfish. The catfish is created as a new born (age zero
33	     * and not hungry).
34	     * 
35	     * @param time The time in the simulation.
36	     * @param field The field currently occupied.
37	     * @param location The location within the field.
38	     * @param parentDiseases The diseases the parent of this catfish had.
39	     */
40	    private Catfish(Time time, Field field, Location location, int age, int foodLevel)
41	    {
42	        super(time, field, location);
43	        female = rand.nextBoolean();
44	        nocturnal = true;
45	        canGoLand = false;
46	        canGoWater = true;
47	        this.age = age;
48	        this.foodLevel = foodLevel;
49	    }
50	
51	    public Catfish(Time time, Field field, Location location, Set<Disease> parentDiseases)
52	    {
53	        this(time, field, location, 0, MAX_FOOD);
54	        inheritDiseases(parentDiseases);
55	    }
56	
57	    public Catfish(Time time, Field field, Location location)
58	    {
59	        this(time, field, location, rand.nextInt(MAX_AGE), rand.nextInt(MAX_FOOD) + 1);
60	        initStartingDiseases(Simulator.diseases);
61	    }
62	
63	    /**
64	     * Create a Map with a key of the prey class
65	     * and a value of the food level is given when eaten.
66	     * @return The prey food value Map.
67	     */
68	    private static Map<Class<? extends Actor>, Integer> createPreyFoodValueMap()
69	    {
70	        Map<Class<? extends Actor>, Integer> mapTemp = new HashMap<>();
71	        mapTemp.put(Water_Fern.class, 3);
72	        return mapTemp;
73	    }
74	
75	    protected int getBreedingAge() { return BREEDING_AGE; }
76	    protected double getBreedingProbability() { return BREEDING_PROBABILITY; }
77	    protected int getMaxLitterSize() { return MAX_LITTER_SIZE; }
78	
79	    /**
80	     * Returns the max food level that the catfish can have.
81	     * @return The max food level that the catfish can have.
82	     */
83	    public int getMaxFood()
84	    {
85	        return MAX_FOOD;
86	    }
87	
88	    /**
89	     * Returns the max age that the catfish can have before dying.
90	     * @return The max age that the catfish can have before dying.
91	     */
92	    public int getMaxAge()
93	    {
94	        return MAX_AGE;
95	    }
96	
97	    /**
98	     * Returns the prey food values Map.
99	     * @return The prey food values Map.
100	     */
101	    public Map<Class<? extends Actor>, Integer> getPreyFoodValuesMap()
102	    {
103	        return PREY_FOOD_VALUES;
104	    }
105	
106	    public Animal spawnOffspring(Location loc, Set<Disease> parentDiseases)
107	    {
108	        return new Catfish(getTime(), getField(), loc, parentDiseases);
109	    }
110	
111	    public Animal spawnRandom(Location loc)
112	    {
