1	import java.util.Collections;
2	import java.util.Iterator;
3	import java.util.LinkedList;
4	import java.util.List;
5	import java.util.Random;
6	import java.util.Set;
7	import java.util.HashSet;
8	import java.util.HashMap;
9	import java.util.Map;
10	
11	/**
12	 * Represent a rectangular grid of field positions.
13	 * Each position is able to store a single actor, either an animal or plant.
14	 *
15	 *
16	 * @version 27.02.22
17	 */
18	public class Field
19	{
20	    // A random number generator for providing random locations.
21	    private static final Random rand = Randomizer.getRandom();
22	    private static final int MAX_ALTITUDE = 5;
23	    // The depth and width of the field.
24	    private int depth, width;
25	    // Storage for the animals, plants, weather and altitude.
26	    private Object[][] animalField;
27	    private Object[][] plantField;
28	    private Map<String, double[][]> weatherField;
29	    private int[][] altitudeField;
30	    private  int waterLevel;
31	    private static final int maxWaterLevel = 3;
32	    private static final int minWaterLevel = 1;
33	
34	    /**
35	     * Represent a field of the given dimensions.
36	     * @param depth The depth of the field.
37	     * @param width The width of the field.
38	     */
39	    public Field(int depth, int width)
40	    {
41	        this.depth = depth;
42	        this.width = width;
43	        animalField = new Object[depth][width];
44	        plantField = new Object[depth][width];
45	        weatherField = createWeatherFieldMap(depth, width);
46	        altitudeField = new int[depth][width];
47	        waterLevel = 3;
48	    }
49	
50	    /**
51	     * Create a Map with a key of the weather condition attribute name
52	     * and a value of weather attribute.
53	     * @param depth The depth of the field.
54	     * @param width The width of the field.
55	     * @return The weather field Map.
56	     */
57	    private Map<String, double[][]> createWeatherFieldMap(int depth, int width)
58	    {
59	        Map<String, double[][]> mapTemp = new HashMap<>();
60	        WeatherCond weatherTemp = WeatherCond.Sunny;
61	        for (String weatherAttribute : weatherTemp.getWeatherAttributesMap().keySet()) {
62	            mapTemp.put(weatherAttribute, new double[depth][width]);
63	        }
64	        return mapTemp;
65	    }
66	
67	    /**
68	     * Empty the field.
69	     */
70	    public void clear()
71	    {
72	        for(int row = 0; row < depth; row++) {
73	            for(int col = 0; col < width; col++) {
74	                animalField[row][col] = null;
75	                plantField[row][col] = null;
76	                for (String weatherAttribute : weatherField.keySet()) {
77	                    weatherField.get(weatherAttribute)[row][col] = 0;
78	                }
79	                altitudeField[row][col] = MAX_ALTITUDE;
80	            }
81	        }
82	        generateTerrain();
83	    }
84	
85	    /**
86	     * Clear the given location.
87	     * The type of actor is specified to clear the correct actor field.
88	     * @param actor The actor in the location being cleared.
89	     * @param location The location to clear.
90	     */
91	    public void clear(Actor actor, Location location)
92	    {
93	        if (actor instanceof Animal){
94	            animalField[location.getRow()][location.getCol()] = null;
95	        }
96	        else if (actor instanceof Plant){
97	            plantField[location.getRow()][location.getCol()] = null;
98	        }
99	    }
100	
101	    /**
102	     * Place an actor at the given location.
103	     * If there is already an actor at the location it will
104	     * be lost.
105	     * @param actor The actor to be placed.
106	     * @param row Row coordinate of the location.
107	     * @param col Column coordinate of the location.
108	     */
109	    public void place(Object actor, int row, int col)
110	    {
111	        place(actor, new Location(row, col));
112	    }
113	
114	    /**
115	     * Place an actor at the given location.
116	     * If there is already an actor at the location it will
117	     * be lost.
118	     * @param actor The actor to be placed.
119	     * @param location Where to place the animal.
120	     */
121	    public void place(Object actor, Location location)
122	    {
123	        if (actor instanceof Animal) {
124	            animalField[location.getRow()][location.getCol()] = actor;
125	        }
126	        else if (actor instanceof Plant) {
127	            plantField[location.getRow()][location.getCol()] = actor;
128	        }
129	    }
130	
131	    /**
132	     * Return the actor at the given location, if any.
133	     * @param location Where in the field.
134	     * @return The actor at the given location, or null if there is none.
135	     */
136	    public Object getObjectAt(Location location)
137	    {
138	        return getObjectAt(location.getRow(), location.getCol());
139	    }
140	
141	    /**
142	     * Return the actor at the given location, if any.
143	     * Animals are prioritised over Plants, and are returned if both
144	     * are present in that location.
145	     * @param row The desired row.
146	     * @param col The desired column.
147	     * @return The actor at the given location, or null if there is none.
148	     */
149	    public Object getObjectAt(int row, int col)
150	    {
151	        if (animalField[row][col] != null) {
152	            return animalField[row][col];
153	        }
154	        return plantField[row][col];
155	    }
156	
157	    /**
158	     * Generate a random location that is adjacent to the
159	     * given location, or is the same location.
160	     * The returned location will be within the valid bounds
161	     * of the field.
162	     * @param location The location from which to generate an adjacency.
163	     * @return A valid location within the grid area.
164	     */
165	    public Location randomAdjacentLocation(Location location)
166	    {
167	        List<Location> adjacent = adjacentLocations(location);
168	        return adjacent.get(0);
169	    }
170	
171	    /**
172	     * Get a shuffled list of the free adjacent locations.
173	     * @param actor The actor finding free adjacent locations.
174	     * @param location Get locations adjacent to this.
175	     * @return A list of free adjacent locations.
176	     */
177	    public List<Location> getFreeAdjacentLocations(Actor actor, Location location)
178	    {
179	        List<Location> free = new LinkedList<>();
180	        List<Location> adjacent = adjacentLocations(location);
181	
182	        for(Location next : adjacent) {
183	
184	            if (getObjectAt(next) == null|| (actor instanceof Animal && getObjectAt(next) instanceof Plant)){
185	                if ((actor.canMoveOnLand() && actor.canMoveOnWater()) || (isUnderWater(next.getRow(), next.getCol()) && actor.canMoveOnWater()) || (!isUnderWater(next.getRow(), next.getCol()) && actor.canMoveOnLand())){
186	                    free.add(next);
187	                }
188	            }
189	        }
190	        return free;
191	    }
192	
193	    /**
194	     * Try to find a free location that is adjacent to the
195	     * given location. If there is none, return null.
196	     * The returned location will be within the valid bounds
197	     * of the field.
198	     * @param actor The actor finding a free adjacent location.
199	     * @param location The location from which to generate an adjacency.
200	     * @return A valid location within the grid area.
201	     */
202	    public Location freeAdjacentLocation(Actor actor, Location location)
203	    {
204	        // The available free ones.
205	        List<Location> free = getFreeAdjacentLocations(actor, location);
206	        if(free.size() > 0) {
207	            return free.get(0);
208	        }
209	        else {
210	            return null;
211	        }
212	    }
213	
214	    /**
215	     * Return a shuffled list of locations adjacent to the given one.
216	     * The list will not include the location itself.
217	     * All locations will lie within the grid.
218	     * @param location The location from which to generate adjacencies.
219	     * @return A list of locations adjacent to that given.
220	     */
221	    public List<Location> adjacentLocations(Location location)
222	    {
223	        assert location != null : "Null location passed to adjacentLocations";
224	        // The list of locations to be returned.
225	        List<Location> locations = new LinkedList<>();
226	        if(location != null) {
227	            int row = location.getRow();
228	            int col = location.getCol();
229	            for(int roffset = -1; roffset <= 1; roffset++) {
230	                int nextRow = row + roffset;
231	                if(nextRow >= 0 && nextRow < depth) {
232	                    for(int coffset = -1; coffset <= 1; coffset++) {
233	                        int nextCol = col + coffset;
234	                        // Exclude invalid locations and the original location.
235	                        if(nextCol >= 0 && nextCol < width && (roffset != 0 || coffset != 0)) {
236	                            locations.add(new Location(nextRow, nextCol));
237	                        }
238	                    }
239	                }
240	            }
241	
242	            // Shuffle the list. Several other methods rely on the list
243	            // being in a random order.
244	            Collections.shuffle(locations, rand);
245	        }
246	        return locations;
247	    }
248	
249	    /**
250	     * Return the depth of the field.
251	     * @return The depth of the field.
252	     */
253	    public int getDepth()
254	    {
255	        return depth;
256	    }
257	
258	    /**
259	     * Return the width of the field.
260	     * @return The width of the field.
261	     */
262	    public int getWidth()
263	    {
264	        return width;
265	    }
266	
267	    /**
268	     * Set the values of each weather attributes field uniformly
269	     * distributed around a specified average.
270	     * @param weather The weather condition.
271	     */
272	    public void setWeatherField(WeatherCond weather) 
273	    {
274	        for (String weatherAttribute : weatherField.keySet()) {
275	            double avgWeather = weather.getWeatherAttributesMap().get(weatherAttribute);
276	            for(int row = 0; row < depth; row++) {
277	                for(int col = 0; col < width; col++) {
278	                    weatherField.get(weatherAttribute)[row][col] = avgWeather + (rand.nextDouble() - 0.5) * 2 / 5;
279	                }
280	            }
281	        }
282	
283	        if(weather.getDampness() > 0.7 && waterLevel < maxWaterLevel){
284	            waterLevel += 1;
285	        }
286	
287	        else if (waterLevel> minWaterLevel){
288	            if(weather.getBrightness() > 0.9 && waterLevel > minWaterLevel + 1){
289	                waterLevel -=2;
290	            }
291	            else {
292	                waterLevel -= 1;
293	            }
294	        }
295	    }
296	
297	    /**
298	     * Returns the weather attribute value at a specified location.
299	     * @param weatherAttribute The String name of the weather attribute.
300	     * @param loc The location.
301	     * @return The weather attribute value at the specified location.
302	     */
303	    public double getWeatherAttributeValueAt(String weatherAttribute, Location loc)
304	    {
305	        return weatherField.get(weatherAttribute)[loc.getRow()][loc.getCol()];
306	    }
307	
308	    /**
309	     * Returns whether or not the location with the specified row and column
310	     * is under water.
311	     * @param row The desired row.
312	     * @param col The desired column.
313	     * @return Whether or not the location is under water.
314	     */
315	    public boolean isUnderWater(int row, int col)
316	    {
317	        return altitudeField[row][col] <= waterLevel;
318	    }
319	
320	    /**
321	     * Randomly generates altitude numbers in the altitude field.
322	     */
323	    public void generateTerrain()
324	    {
325	        Location centre = new Location(rand.nextInt(depth), rand.nextInt(width));
326	        boolean horizontal = rand.nextBoolean();
327	        if (horizontal) {
328	            for (int z = 0; z < width; z++) {
329	                altitudeField[centre.getRow()][z] = 0;
330	            }
331	            int stop = 0;
332	            int x = 0;
333	            while (stop < depth / 6) {
334	                x++;
335	                Location topOrLeft = new Location(centre.getRow() - x, centre.getCol() - x);
336	                stop += incrementAltitude(topOrLeft.getRow(), topOrLeft.getCol(), topOrLeft.getRow() + 1, topOrLeft.getCol() + 1);
337	                Location bottomOrRight = new Location(centre.getRow() + x, centre.getCol() + x);
338	                stop += incrementAltitude(bottomOrRight.getRow(), bottomOrRight.getCol(), bottomOrRight.getRow() - 1, bottomOrRight.getCol() - 1);
339	                for (int z = 0; z < width; z++) {
340	                    stop += incrementAltitude(topOrLeft.getRow(), z, topOrLeft.getRow() + 1, z);
341	                    stop += incrementAltitude(bottomOrRight.getRow(), z, bottomOrRight.getRow() - 1, z);
342	                }
343	            }
344	        }
345	        else {
346	            for (int z = 0; z < depth; z++) {
347	                altitudeField[z][centre.getCol()] = 0;
348	            }
349	            int stop = 0;
350	            int x = 0;
351	            while (stop < width / 9) {
352	                x++;
353	                Location topOrLeft = new Location(centre.getRow() - x, centre.getCol() - x);
354	                stop += incrementAltitude(topOrLeft.getRow(), topOrLeft.getCol(), topOrLeft.getRow() + 1, topOrLeft.getCol() + 1);
355	                Location bottomOrRight = new Location(centre.getRow() + x, centre.getCol() + x);
356	                stop += incrementAltitude(bottomOrRight.getRow(), bottomOrRight.getCol(), bottomOrRight.getRow() - 1, bottomOrRight.getCol() - 1);
357	                for (int z = 0; z < width; z++) {
358	                    stop += incrementAltitude(z, topOrLeft.getCol(), z, topOrLeft.getCol() + 1);
359	                    stop += incrementAltitude(z, bottomOrRight.getCol(), z, bottomOrRight.getCol() - 1);
360	                }
361	            }
362	        }
363	    }
364	    
365	    private int incrementAltitude(int row, int col, int adjRow, int adjCol)
366	        {
367	        if (row < depth && col < width && adjRow < depth && adjCol < width && row > 0 && col > 0 && adjRow > 0 && adjCol > 0) {
368	            int newAltitude;
369	            if (rand.nextInt(depth * width / 1000) == 0) {
370	                newAltitude = altitudeField[adjRow][adjCol] + 1;
371	            }
372	            else {
373	                newAltitude = altitudeField[adjRow][adjCol];
374	            }
375	            if (newAltitude >= MAX_ALTITUDE) {
376	                altitudeField[row][col] = MAX_ALTITUDE;
377	            }
378	            else if (newAltitude <= 0) {
379	                altitudeField[row][col] = 0;
380	            }
381	            else {
382	                altitudeField[row][col] = newAltitude;
383	            }
384	            if (altitudeField[row][col] == MAX_ALTITUDE) {
385	                return 1;
386	            }
387	        }
388	        return 0;
389	    }
390	}
