1	import java.awt.Color;
2	import java.util.HashMap;
3	
4	/**
5	 * This class collects and provides some statistical data on the state 
6	 * of a field. It is flexible: it will create and maintain a counter 
7	 * for any class of object that is found within the field.
8	 *
9	 * @version 27.02.22
10	 */
11	public class FieldStats
12	{
13	    // Counters for each type of entity (fox, rabbit, etc.) in the simulation.
14	    private HashMap<Class, Counter> counters;
15	    // Whether the counters are currently up to date.
16	    private boolean countsValid;
17	    private Time time; 
18	
19	    /**
20	     * Construct a FieldStats object.
21	     */
22	    public FieldStats()
23	    {
24	        // Set up a collection for counters for each type of animal that
25	        // we might find
26	        counters = new HashMap<>();
27	        countsValid = true;
28	    }
29	
30	    /**
31	     * Get details of what is in the field.
32	     * @return A string describing what is in the field.
33	     */
34	    public String getPopulationDetails(Field field)
35	    {
36	        StringBuffer buffer = new StringBuffer();
37	        if(!countsValid) {
38	            generateCounts(field);
39	        }
40	        for(Class key : counters.keySet()) {
41	            Counter info = counters.get(key);
42	            buffer.append(info.getName());
43	            buffer.append(": ");
44	            buffer.append(info.getCount());
45	            buffer.append(' ');
46	        }
47	        return buffer.toString();
48	    }
49	
50	    /**
51	     * Invalidate the current set of statistics; reset all 
52	     * counts to zero.
53	     */
54	    public void reset()
55	    {
56	        countsValid = false;
57	        for(Class key : counters.keySet()) {
58	            Counter count = counters.get(key);
59	            count.reset();
60	        }
61	    }
62	
63	    /**
64	     * Increment the count for one class of actor.
65	     * @param actorClass The class of actor to increment.
66	     */
67	    public void incrementCount(Class actorClass)
68	    {
69	        Counter count = counters.get(actorClass);
70	        if(count == null) {
71	            // We do not have a counter for this species yet.
72	            // Create one.
73	            count = new Counter(actorClass.getName());
74	            counters.put(actorClass, count);
75	        }
76	        count.increment();
77	        
78	    }
79	
80	    /**
81	     * Indicate that an animal count has been completed.
82	     */
83	    public void countFinished()
84	    {
85	        countsValid = true;
86	    }
87	
88	    /**
89	     * Determine whether the simulation is still viable.
90	     * I.e., should it continue to run.
91	     * @return true If there is more than one species alive.
92	     */
93	    public boolean isViable(Field field)
94	    {
95	        // How many counts are non-zero.
96	        int nonZero = 0;
97	        if(!countsValid) {
98	            generateCounts(field);
99	        }
100	        for(Class key : counters.keySet()) {
101	            Counter info = counters.get(key);
102	            if(info.getCount() > 0) {
103	                nonZero++;
104	            }
105	        }
106	        return nonZero > 1;
107	    }
108	
109	    /**
110	     * Generate counts of the number of actors.
111	     * These are not kept up to date as actors
112	     * are placed in the field, but only when a request
113	     * is made for the information.
114	     * @param field The field to generate the stats for.
115	     */
116	    private void generateCounts(Field field)
117	    {
118	        reset();
119	        for(int row = 0; row < field.getDepth(); row++) {
120	            for(int col = 0; col < field.getWidth(); col++) {
121	                Object actor = field.getObjectAt(row, col);
122	                if(actor != null) {
123	                    incrementCount(actor.getClass());
124	                }
125	                
126	            }
127	        }
128	        countsValid = true;
129	    }
130	}
