5	/**
6	 * A class representing shared characteristics of plants.
7	 *
8	 * @version 27.02.22
9	 */
10	public abstract class Plant extends Actor
11	{
12	
13	    protected double waterLevel;
14	    protected double sunLightLevel;
15	    private static final double maxWaterLevel = 2.5;
16	
17	    /**
18	     * Create a new plant at location in field with time as well.
19	     * With a set that will add any disease that it catches
20	     * 
21	     * @param field The field currently occupied.
22	     * @param location The location within the field.
23	     * @param time The time in the simulation
24	     */
25	    public Plant(Time time, Field field, Location location)
26	    {
27	        super(time, field, location);
28	        waterLevel = 1.5;
29	        sunLightLevel = 1.5;
30	    }
31	
32	    /**
33	     * Make this plant act - that is: make it do
34	     * whatever it wants/needs to do.
35	     * Checks weather and updates water and sunlight levels accordingly.
36	     * @param newPlants A list to receive newly born plants.
37	     * @param weather The weather condition of the simulation.
38	     */
39	    public void act(List<Actor> newPlants, WeatherCond weather)
40	    {
41	        super.act(newPlants, weather);
42	        if (isAlive()){
43	            waterLevel-=0.5;
44	            sunLightLevel-= 0.25;
45	            sunLightLevel += getField().getWeatherAttributeValueAt("brightness", getLocation());
46	            if (waterLevel +getField().getWeatherAttributeValueAt("dampness", getLocation()) > maxWaterLevel){
47	                waterLevel = maxWaterLevel;
48	            }
49	            else {
50	                waterLevel += getField().getWeatherAttributeValueAt("dampness", getLocation());
51	            }
52	            if (waterLevel < 0 || sunLightLevel <= 0){
53	                setDead();
54	            }
55	            else {
56	                giveBirth(newPlants);            
57	            }
58	        }
59	    }
60	
61	    /**
62	     * Returns how many plants are produced during birth.
63	     * Uses the abstract breeding parameters defined by each subclass.
64	     * @return The number of births (may be zero).
65	     */
66	    public int breed()
67	    {
68	        Random rand = Randomizer.getRandom();
69	        if(canBreed() && rand.nextDouble() <= getBreedingProbability()) {
70	            return rand.nextInt(getMaxLitterSize()) + 1;
71	        }
72	        return 0;
73	    }
74	
75	    private boolean canBreed()
76	    {
77	        return age >= getBreedingAge();
78	    }
79	
80	    abstract protected int getBreedingAge();
81	    abstract protected double getBreedingProbability();
82	    abstract protected int getMaxLitterSize();
83	
84	    abstract protected Plant spawnOffspring(Location loc, Set<Disease> parentDiseases);
85	    abstract protected Plant spawnRandom(Location loc);
86	}

