9	
10	/**
11	 * A simple predator-prey simulator, based on a rectangular field
12	 * containing actors, or animals and plants.
13	 *
14	 * @version 27.02.22
15	 */
16	public class Simulator
17	{
18	    // Constants representing configuration information for the simulation.
19	    // The default width for the grid.
20	    private static final int DEFAULT_WIDTH = 250;
21	    // The default depth of the grid.
22	    private static final int DEFAULT_DEPTH = 250;
23	    // List of actors in the field.
24	    private List<Actor> actors;
25	    // The probabilities that actors will be created in any given grid position.
26	    private Map<Actor,Double> actorCreationProb; 
27	    // List of diseases in the simulation.
28	    static final List<Disease> diseases = createDiseases();
29	    // The current state of the field.
30	    private Field field;
31	    // The current step of the simulation.
32	    private int step;
33	    // A graphical view of the simulation.
34	    private SimulatorView view;
35	    // The current time in the field.
36	    private Time time;
37	    // The current weather condition of the field.
38	    private WeatherCond weatherCond;
39	
40	    /**
41	     * Construct a simulation field with default size.
42	     */
43	    public Simulator()
44	    {
45	        this(DEFAULT_DEPTH, DEFAULT_WIDTH);
46	    }
47	
48	    /**
49	     * Create a simulation field with the given size.
50	     * @param depth Depth of the field. Must be greater than zero.
51	     * @param width Width of the field. Must be greater than zero.
52	     */
53	    public Simulator(int depth, int width)
54	    {
55	        if(width <= 0 || depth <= 0) {
56	            System.out.println("The dimensions must be greater than zero.");
57	            System.out.println("Using default values.");
58	            depth = DEFAULT_DEPTH;
59	            width = DEFAULT_WIDTH;
60	        }
61	
62	        actors = new ArrayList<>();
63	        field = new Field(depth, width);
64	        time = new Time(3);
65	        actorCreationProb = createActorCreationProb();
66	        weatherCond = WeatherCond.Sunny; //Sunny weather is default 
67	
68	        // Create a view of the state of each location in the field.
69	        view = new SimulatorView(depth, width);
70	        view.setColor(Lemur.class, Color.RED.darker());
71	        view.setColor(Panther.class, Color.ORANGE);
72	        view.setColor(Grass.class, Color.GREEN.darker());
73	        view.setColor(Water_Fern.class, Color.GREEN.brighter());
74	        view.setColor(Alligator.class, Color.LIGHT_GRAY);
75	        view.setColor(Salamander.class, Color.MAGENTA);
76	        view.setColor(Catfish.class, Color.BLACK);
77	
78	        
79	        weatherCond.setTime(time);
80	        // Setup a valid starting point.
81	        reset();
82	    }
83	
84	    /**
85	     * Create a Map with a key of an Actor object, one of each subclass of Animal and Plant,
86	     * and a value of the creation proability.
87	     * @return The actor creation prbability Map.
88	     */
89	    private Map<Actor,Double> createActorCreationProb()
90	    {
91	        Map<Actor,Double> tempMap = new HashMap<>();
92	        Location location = new Location(0, 0);
93	        tempMap.put(new Grass(time, field, location),0.8);
94	        tempMap.put(new Water_Fern(time, field, location),0.9);
95	        tempMap.put(new Salamander(time, field, location),0.5);
96	        tempMap.put(new Catfish(time, field, location),0.7);
97	        tempMap.put(new Lemur(time, field, location),0.45);
98	        tempMap.put(new Panther(time, field, location),0.3);
99	        tempMap.put(new Alligator(time, field, location),0.25);
100	        
101	        
102	        return tempMap;
103	    }
104	
105	    /**
106	     * Create a List of all the diseases in the simulation, specify which actors start with the disease and which actors can catch the disease.
107	     * Starting and affected actors are specified by a Map with a String key and double value, of probability to get disease for starting actors,
108	     * and disease severity for affected actors. Severity ranges from 0.0 to 1.0, 0.0 being completely fatal as soon as contracted, and 1.0 meaning
109	     * the actor is just a disease carrier.
110	     * @return The diseases List.
111	     */
112	    private static List<Disease> createDiseases()
113	    {
114	        List<Disease> list = new ArrayList<>();
115	        Disease dengue = new Disease("dengue", true, true);
116	
117	        dengue.getActorsAffectedMap().put(Lemur.class, 0.9);
118	        dengue.getActorsAffectedMap().put(Panther.class, 0.6);
119	        dengue.getActorsAffectedMap().put(Alligator.class, 0.6);
120	
121	        dengue.getStartingActorsMap().put(Lemur.class, 0.4);
122	        list.add(dengue);
123	
124	        Disease river_fever = new Disease("river_fever", true, false);
125	
126	        river_fever.getActorsAffectedMap().put(Water_Fern.class, 1.0);
127	        river_fever.getActorsAffectedMap().put(Catfish.class, 0.7);
128	        river_fever.getActorsAffectedMap().put(Salamander.class, 0.8);
129	
130	        river_fever.getStartingActorsMap().put(Water_Fern.class, 0.4);
131	        list.add(river_fever);
132	        
133	        return Collections.unmodifiableList(list);
134	    }
135	
136	    /**
137	     * Run the simulation from its current state for a reasonably long period,
138	     * (4000 steps).
139	     */
140	    public void runLongSimulation()
141	    {
142	        simulate(4000);
143	    }
144	
145	    /**
146	     * Run the simulation from its current state for the given number of steps.
147	     * Stop before the given number of steps if it ceases to be viable.
148	     * @param numSteps The number of steps to run for.
149	     */
150	    public void simulate(int numSteps)
151	    {
152	        for(int step = 1; step <= numSteps && view.isViable(field); step++) {
153	            simulateOneStep();
154	            delay(60);
155	        }
156	    }
157	
158	    /**
159	     * Run the simulation from its current state for a single step.
160	     * Iterate over the whole field updating the state of each actor.
161	     */
162	    public void simulateOneStep()
163	    {
164	        step++;
165	        time.incrementTime(); 
166	        weatherCond = weatherCond.nextCondition();
167	        // Provide space for newborn actors.
168	
169	        List<Actor> newActors = new ArrayList<>();        
170	        // Let all actors act.
171	        for(Iterator<Actor> it = actors.iterator(); it.hasNext(); ) {
172	            Actor actor = it.next();
173	            actor.act(newActors, weatherCond);
174	            if(! actor.isAlive()) {
175	                it.remove();
176	            }
177	        }
178	
179	        // Add the newly born actors to the main lists.
180	        actors.addAll(newActors);
181	
182	        view.showStatus(step, field, weatherCond, diseases);
183	        field.setWeatherField(weatherCond);
184	    }
185	
186	    /**
187	     * Reset the simulation to a starting position.
188	     */
189	    public void reset()
190	    {
191	        step = 0;
192	        actors.clear();
193	        populate();
194	
195	        // Show the starting state in the view.
196	        view.showStatus(step, field, weatherCond, diseases);
197	    }
198	
199	    /**
200	     * Randomly populate the field with actors.
201	     * Actors can only populate areas they will survive in
202	     * i.e. actors that will not survive in water cannot be placed there.
203	     */
204	    private void populate()
205	    {
206	        Random rand = Randomizer.getRandom();
207	        field.clear();
208	        for(int row = 0; row < field.getDepth(); row++) {
209	            for(int col = 0; col < field.getWidth(); col++) {
210	                for(Actor actor : actorCreationProb.keySet()) {
211	                    if(rand.nextDouble() <= actorCreationProb.get(actor) && terrainCompatible(actor, row, col)) {
212	                        actors.add(actor.spawnRandom(new Location(row, col)));
213	                        break;
214	                    }
215	                }
216	            }
217	        }
218	    }
219	
220	    private boolean terrainCompatible(Actor actor, int row, int col)
221	    {
222	        return (actor.canMoveOnLand() && actor.canMoveOnWater())
223	            || (field.isUnderWater(row, col) && actor.canMoveOnWater())
224	            || (!field.isUnderWater(row, col) && actor.canMoveOnLand());
225	    }
226	
227	    /**
228	     * Pause for a given time.
229	     * @param millisec  The time to pause for, in milliseconds
230	     */
231	    private void delay(int millisec)
232	    {
233	        try {
234	            Thread.sleep(millisec);
235	        }
236	        catch (InterruptedException ie) {
237	            // wake up
238	        }
239	    }
240	}
