100	    /**
101	     * Show the current status of the field.
102	     * @param step Which iteration step it is.
103	     * @param field The field whose status is to be displayed.
104	     */
105	    public void showStatus(int step, Field field, WeatherCond weather, List<Disease> diseases)
106	    {
107	        if(!isVisible()) {
108	            setVisible(true);
109	        }
110	
111	        stepLabel.setText(STEP_PREFIX + step + "   Weather : " + weather);
112	        stats.reset();
113	
114	        fieldView.preparePaint();
115	        
116	        int[] diseaseCount = new int[diseases.size()];
117	        String diseaseDisplay = "";
118	
119	        for(int row = 0; row < field.getDepth(); row++) {
120	            for(int col = 0; col < field.getWidth(); col++) {
121	                Object actor = field.getObjectAt(row, col);
122	                if(actor != null) {
123	                    
124	                    Actor mainActor = (Actor) actor;
125	                    
126	                    for (int x = 0; x < diseases.size(); x++) {
127	                        if (mainActor.getActorDiseaseSet().contains(diseases.get(x))) {
128	                            diseaseCount[x]++;
129	                        }
130	                    }
131	                        
132	                    stats.incrementCount(actor.getClass());
133	                    fieldView.drawMark(col, row, getColor(actor.getClass()));
134	                }
135	                // If the field is underwater at that location, draw in blue
136	                else if (field.isUnderWater(row, col)){ 
137	                    fieldView.drawMark(col, row, Color.cyan);
138	                }
139	                else {
140	                    fieldView.drawMark(col, row, EMPTY_COLOR);
141	                }
142	            }
143	        }
144	        stats.countFinished();
145	        
146	        for (int x = 0; x < diseases.size(); x++) {
147	            diseaseDisplay = diseaseDisplay + diseases.get(x).getName() + ": " + diseaseCount[x] + " ";
148	        }
