156	     * @return true If there is more than one species alive.
157	     */
158	    public boolean isViable(Field field)
159	    {
160	        return stats.isViable(field);
161	    }
162	
163	    /**
164	     * Provide a graphical view of a rectangular field. This is 
165	     * a nested class (a class defined inside a class) which
166	     * defines a custom component for the user interface. This
167	     * component displays the field.
168	     * This is rather advanced GUI stuff - you can ignore this 
169	     * for your project if you like.
170	     */
171	    private class FieldView extends JPanel
172	    {
173	        private final int GRID_VIEW_SCALING_FACTOR = 6;
174	
175	        private int gridWidth, gridHeight;
176	        private int xScale, yScale;
177	        Dimension size;
178	        private Graphics g;
179	        private Image fieldImage;
180	
181	        /**
182	         * Create a new FieldView component.
183	         */
184	        public FieldView(int height, int width)
185	        {
186	            gridHeight = height;
187	            gridWidth = width;
188	            size = new Dimension(0, 0);
189	        }
190	
191	        /**
192	         * Tell the GUI manager how big we would like to be.
193	         */
194	        public Dimension getPreferredSize()
195	        {
196	            return new Dimension(gridWidth * GRID_VIEW_SCALING_FACTOR,
197	                gridHeight * GRID_VIEW_SCALING_FACTOR);
198	        }
199	
200	        /**
201	         * Prepare for a new round of painting. Since the component
202	         * may be resized, compute the scaling factor again.
203	         */
204	        public void preparePaint()
205	        {
206	            if(! size.equals(getSize())) {  // if the size has changed...
207	                size = getSize();
208	                fieldImage = fieldView.createImage(size.width, size.height);
209	                g = fieldImage.getGraphics();
210	
211	                xScale = size.width / gridWidth;
212	                if(xScale < 1) {
213	                    xScale = GRID_VIEW_SCALING_FACTOR;
214	                }
215	                yScale = size.height / gridHeight;
216	                if(yScale < 1) {
217	                    yScale = GRID_VIEW_SCALING_FACTOR;
218	                }
219	            }
220	        }
221	
222	        /**
223	         * Paint on grid location on this field in a given color.
224	         */
225	        public void drawMark(int x, int y, Color color)
226	        {
227	            g.setColor(color);
228	            g.fillRect(x * xScale, y * yScale, xScale-1, yScale-1);
229	        }
230	
231	        /**
232	         * The field view component needs to be redisplayed. Copy the
233	         * internal image to screen.
234	         */
235	        public void paintComponent(Graphics g)
236	        {
237	            if(fieldImage != null) {
238	                Dimension currentSize = getSize();
239	                if(size.equals(currentSize)) {
240	                    g.drawImage(fieldImage, 0, 0, null);
241	                }
242	                else {
243	                    // Rescale the previous image.
244	                    g.drawImage(fieldImage, 0, 0, currentSize.width, currentSize.height, null);
245	                }
246	            }
247	        }
248	    }
249	}
