1	/**
2	 * Time class that deals with the time that is passed for each step taken 
3	 * Used for the day and night cycle
4	 *
5	 * @version 27.02.22
6	 */
7	public class Time
8	{
9	    private int time;
10	    // How much time will increment by for each step
11	    private int timeStep;
12	
13	    /**
14	     * Creates the time, sets it to 0 and takes how much time will increment by
15	     * @param timeStep How much time will increment by for each step
16	     */
17	    public Time(int timeStep)
18	    {
19	        time = 0;
20	        this.timeStep = timeStep;
21	    }
22	
23	    /**
24	     * Used to increment the time by the time step, keeps it at range 0-24
25	     * to simulate a 24hr time system
26	     */
27	    public void incrementTime()
28	    {
29	        time = (time + timeStep) % 24;
30	    }
31	
32	    /**
33	     * Used to check if it is day which is true or if its night
34	     * @return true if day, false if it is night
35	     */
36	    public boolean isDay(){
37	        if (time < 18 && time > 6){
38	            return true;
39	        }
40	        else {
41	            return false;
42	        }
43	    }
44	}

