1	import java.util.HashMap;
2	import java.util.Map;
3	
4	/**
5	 * Disease that can spread between animals by animals eating infected actors and through birth meaning the
6	 * parents and and child get each others' diseases.
7	 * The disease affects different animals with different multipliers, and the disease can be created
8	 * onto an actor during the start of the simulation.
9	 *
10	 * @version 27.02.22
11	 */
12	public class Disease
13	{
14	    private String name;
15	    private boolean spreadByBirth;
16	    private boolean spreadByEating;
17	    // actor class mapped to disease severity multiplier (0.0 = fatal, 1.0 = carrier only)
18	    private Map<Class<? extends Actor>, Double> actorsAffected;
19	    // actor class mapped to probability of starting with this disease
20	    private Map<Class<? extends Actor>, Double> startingActors;
21	
22	    /**
23	     * Creates the disease and sets it name, and how it spreads, who it can spread to and
24	     * which actor it starts with.
25	     * @param name The name of the disease
26	     * @param spreadByBirth Whether or not the disease is spread by birth.
27	     * @param spreadByEating Whether or not the disease is spread by eating.
28	     */
29	    public Disease(String name, boolean spreadByBirth,boolean spreadByEating)
30	    {
31	        this.name = name;
32	        this.spreadByBirth = spreadByBirth;
33	        this.spreadByEating = spreadByEating;
34	        actorsAffected = new HashMap<>();
35	        startingActors = new HashMap<>();
36	    }
37	
38	    /**
39	     * Returns the String name of the disease.
40	     * @return The String name of the disease.
41	     */
42	    public String getName()
43	    {
44	        return name;
45	    }
46	
47	    /**
48	     * Used to return if the disease is spread by birth,
49	     * the child gets their parents disease and the mate also gets the disease during
50	     * birth
51	     * @return true if it does spread by birth
52	     */
53	    public boolean isSpreadByBirth()
54	    {
55	        return spreadByBirth;
56	    }
57	
58	    /**
59	     * Used to return if the disease is spread by eating,
60	     * predators can be infected by eating an infected actor
61	     * @return true if it does spread by eating
62	     */
63	    public boolean isSpreadByEating()
64	    {
65	        return spreadByEating;
